package com.foliopro.api.service;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.foliopro.api.dto.ApiDtos.*;
import com.foliopro.api.model.*;
import com.foliopro.api.repository.*;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service
public class FolioService {
 private static final String DEV_USER="development";
 private static final Set<String> COLUMN_KEYS=Set.of("symbol","name","assetType","price","change","trend","sector","score","volume","open","previousClose","dayHigh","dayLow","marketCap","averageVolume","relativeVolume","peRatio","forwardPE","eps","pegRatio","priceToBook","priceToSales","dividendYield","roe","roa","grossMargin","operatingMargin","profitMargin","debtToEquity","revenueGrowth","earningsGrowth","freeCashFlow","analystTarget","week52High","week52Low","movingAverage50","movingAverage200","rsi14","macd","macdSignal","beta","shortFloat","nextEarnings");
 private final PortfolioRepository portfolios; private final HoldingRepository holdings; private final WatchlistRepository watchlists; private final UsaWatchlistItemRepository usaItems; private final IndiaWatchlistItemRepository indiaItems; private final UserPreferencesRepository preferences; private final ObjectMapper mapper;
 public FolioService(PortfolioRepository p,HoldingRepository h,WatchlistRepository w,UsaWatchlistItemRepository ui,IndiaWatchlistItemRepository ii,UserPreferencesRepository u,ObjectMapper m){portfolios=p;holdings=h;watchlists=w;usaItems=ui;indiaItems=ii;preferences=u;mapper=m;}
 @Transactional(readOnly=true) public PageResponse<PortfolioResponse> listPortfolios(int page,int size){Page<PortfolioEntity> result=portfolios.findAll(PageRequest.of(page,size,Sort.by("id").ascending()));return new PageResponse<>(result.map(this::portfolioDto).getContent(),page,size,result.getTotalElements(),result.getTotalPages());}
 @Transactional(readOnly=true) public PortfolioResponse getPortfolio(long id){return portfolioDto(portfolios.findById(id).orElseThrow(()->new NoSuchElementException("Portfolio not found")));}
 @Transactional public PortfolioResponse savePortfolio(Long id,PortfolioRequest request){PortfolioEntity p=id==null?new PortfolioEntity():portfolios.findById(id).orElseThrow(()->new NoSuchElementException("Portfolio not found"));p.setName(request.name().trim());p.setCountry(request.country().trim());p.setCurrency(request.currency());p.setAssetType(request.assetType());p.touch();p=portfolios.save(p);if(id!=null)holdings.deleteByPortfolioId(id);if(request.holdings()!=null)for(HoldingRequest h:request.holdings()){HoldingEntity e=new HoldingEntity();e.setPortfolio(p);e.setSymbol(h.symbol());e.setInstrument(h.instrument());e.setQuantity(h.quantity());e.setAverageCost(h.averageCost());e.setMarketValue(h.marketValue());e.setCurrency(h.currency());holdings.save(e);}return portfolioDto(p);}
 @Transactional public void deletePortfolio(long id){if(!portfolios.existsById(id))throw new NoSuchElementException("Portfolio not found");portfolios.deleteById(id);}
 private PortfolioResponse portfolioDto(PortfolioEntity p){return new PortfolioResponse(p.getId(),p.getName(),p.getCountry(),p.getCurrency(),p.getAssetType(),holdings.findByPortfolioIdOrderById(p.getId()).stream().map(h->new HoldingResponse(h.getSymbol(),h.getInstrument(),h.getQuantity(),h.getAverageCost(),h.getMarketValue(),h.getCurrency())).toList(),false);}
 @Transactional(readOnly=true) public PageResponse<WatchlistResponse> listWatchlists(String market,int page,int size){Page<WatchlistEntity> result=market==null?watchlists.findAll(PageRequest.of(page,size,Sort.by("id").ascending())):watchlists.findByMarket(market,PageRequest.of(page,size,Sort.by("id").ascending()));List<WatchlistEntity> pageWatchlists=result.getContent();List<Long> usaIds=pageWatchlists.stream().filter(UsaWatchlistEntity.class::isInstance).map(WatchlistEntity::getId).toList();List<Long> indiaIds=pageWatchlists.stream().filter(IndiaWatchlistEntity.class::isInstance).map(WatchlistEntity::getId).toList();Map<Long,List<WatchlistItemResponse>> itemsByWatchlist=new HashMap<>();if(!usaIds.isEmpty())for(UsaWatchlistItemEntity item:usaItems.findByWatchlistIdInOrderByIdAsc(usaIds))itemsByWatchlist.computeIfAbsent(item.getWatchlist().getId(),key->new ArrayList<>()).add(itemDto(item));if(!indiaIds.isEmpty())for(IndiaWatchlistItemEntity item:indiaItems.findByWatchlistIdInOrderByIdAsc(indiaIds))itemsByWatchlist.computeIfAbsent(item.getWatchlist().getId(),key->new ArrayList<>()).add(itemDto(item));List<WatchlistResponse> content=pageWatchlists.stream().map(w->watchlistDto(w,itemsByWatchlist.getOrDefault(w.getId(),List.of()))).toList();return new PageResponse<>(content,page,size,result.getTotalElements(),result.getTotalPages());}
  @Transactional(readOnly=true) public WatchlistResponse getWatchlist(long id,int page,int size){WatchlistEntity w=watchlists.findById(id).orElseThrow(()->new NoSuchElementException("Watchlist not found"));Pageable pageable=PageRequest.of(page,size,Sort.by("id").ascending());Page<? extends WatchlistItemEntity> p=w instanceof UsaWatchlistEntity?usaItems.findByWatchlistId(id,pageable):indiaItems.findByWatchlistId(id,pageable);Long userId=w instanceof UsaWatchlistEntity usa?usa.getUserId():null;return new WatchlistResponse(w.getId(),w.getName(),w.getMarket(),w.getCurrency(),userId,p.getContent().stream().map(this::itemDto).toList());}
  @Transactional public WatchlistResponse createWatchlist(WatchlistRequest r){WatchlistEntity w=r.market().equals("US")?new UsaWatchlistEntity():new IndiaWatchlistEntity();w.setName(r.name().trim());if(w instanceof UsaWatchlistEntity usa&&r.userId()!=null)usa.setUserId(r.userId());return watchlistDto(watchlists.save(w));}
 @Transactional public WatchlistResponse renameWatchlist(long id,WatchlistRequest r){WatchlistEntity w=watchlists.findById(id).orElseThrow(()->new NoSuchElementException("Watchlist not found"));if(!w.getMarket().equals(r.market()))throw new IllegalArgumentException("Market cannot be changed when renaming a watchlist");w.setName(r.name().trim());return watchlistDto(watchlists.save(w));}
 @Transactional public void deleteWatchlist(long id){WatchlistEntity w=watchlists.findById(id).orElseThrow(()->new NoSuchElementException("Watchlist not found"));deleteItems(w);watchlists.delete(w);}
 @Transactional public List<WatchlistItemResponse> addItems(long id,BulkItemsRequest request){WatchlistEntity w=watchlists.findById(id).orElseThrow(()->new NoSuchElementException("Watchlist not found"));Set<String> seen=new HashSet<>();List<WatchlistItemResponse> added=new ArrayList<>();for(WatchlistItemRequest r:request.items()){String symbol=r.symbol().toUpperCase(Locale.ROOT);if(!seen.add(symbol)||findItem(w,symbol).isPresent())throw new IllegalArgumentException("Duplicate symbol in watchlist: "+symbol);WatchlistItemEntity e=newItem(w);apply(e,r);added.add(itemDto(saveItem(e)));}return added;}
 @Transactional public WatchlistItemResponse updateItem(long id,String symbol,WatchlistItemRequest r){WatchlistEntity w=watchlists.findById(id).orElseThrow(()->new NoSuchElementException("Watchlist not found"));WatchlistItemEntity e=findItem(w,symbol.toUpperCase(Locale.ROOT)).orElseThrow(()->new NoSuchElementException("Watchlist item not found"));if(!e.getSymbol().equalsIgnoreCase(r.symbol())&&findItem(w,r.symbol().toUpperCase(Locale.ROOT)).isPresent())throw new IllegalArgumentException("Duplicate symbol in watchlist");apply(e,r);return itemDto(saveItem(e));}
 @Transactional public void removeItem(long id,String symbol){WatchlistEntity w=watchlists.findById(id).orElseThrow(()->new NoSuchElementException("Watchlist not found"));WatchlistItemEntity e=findItem(w,symbol.toUpperCase(Locale.ROOT)).orElseThrow(()->new NoSuchElementException("Watchlist item not found"));deleteItem(e);}
 private void apply(WatchlistItemEntity e,WatchlistItemRequest r){e.setSymbol(r.symbol());e.setName(r.name()==null||r.name().isBlank()?r.symbol().toUpperCase(Locale.ROOT):r.name().trim());e.setFavorite(Boolean.TRUE.equals(r.isFavorite()));}
 private WatchlistItemEntity newItem(WatchlistEntity w){if(w instanceof UsaWatchlistEntity usa){UsaWatchlistItemEntity item=new UsaWatchlistItemEntity();item.setWatchlist(usa);return item;}IndiaWatchlistItemEntity item=new IndiaWatchlistItemEntity();item.setWatchlist((IndiaWatchlistEntity)w);return item;}
 private WatchlistItemEntity saveItem(WatchlistItemEntity item){if(item instanceof UsaWatchlistItemEntity usa)return usaItems.save(usa);return indiaItems.save((IndiaWatchlistItemEntity)item);}
 private Optional<WatchlistItemEntity> findItem(WatchlistEntity w,String symbol){if(w instanceof UsaWatchlistEntity)return usaItems.findByWatchlistIdAndSymbol(w.getId(),symbol).map(item->(WatchlistItemEntity)item);return indiaItems.findByWatchlistIdAndSymbol(w.getId(),symbol).map(item->(WatchlistItemEntity)item);}
 private List<WatchlistItemEntity> findItems(WatchlistEntity w){if(w instanceof UsaWatchlistEntity)return usaItems.findByWatchlistId(w.getId()).stream().map(item->(WatchlistItemEntity)item).toList();return indiaItems.findByWatchlistId(w.getId()).stream().map(item->(WatchlistItemEntity)item).toList();}
 private void deleteItem(WatchlistItemEntity item){if(item instanceof UsaWatchlistItemEntity usa)usaItems.delete(usa);else indiaItems.delete((IndiaWatchlistItemEntity)item);}
 private void deleteItems(WatchlistEntity w){if(w instanceof UsaWatchlistEntity)usaItems.deleteByWatchlistId(w.getId());else indiaItems.deleteByWatchlistId(w.getId());}
  private WatchlistResponse watchlistDto(WatchlistEntity w){return watchlistDto(w,findItems(w).stream().map(this::itemDto).toList());}
  private WatchlistResponse watchlistDto(WatchlistEntity w,List<WatchlistItemResponse> items){Long userId=w instanceof UsaWatchlistEntity usa?usa.getUserId():null;return new WatchlistResponse(w.getId(),w.getName(),w.getMarket(),w.getCurrency(),userId,items);}
 private WatchlistItemResponse itemDto(WatchlistItemEntity e){return new WatchlistItemResponse(e.getId(),e.getSymbol(),e.getName(),e.isFavorite());}
 @Transactional public PreferencesResponse getPreferences(){UserPreferencesEntity e=preferences.findByUserKey(DEV_USER).orElseGet(()->{UserPreferencesEntity n=new UserPreferencesEntity();n.setUserKey(DEV_USER);return preferences.save(n);});return preferenceDto(e);}
 @Transactional public PreferencesResponse savePreferences(PreferencesRequest r){for(String key:r.watchlistColumns())if(!COLUMN_KEYS.contains(key))throw new IllegalArgumentException("Unsupported watchlist column: "+key);for(String market:r.favoriteSymbols().keySet())if(!Set.of("US","India").contains(market))throw new IllegalArgumentException("Unsupported market: "+market);try{UserPreferencesEntity e=preferences.findByUserKey(DEV_USER).orElseGet(()->{UserPreferencesEntity n=new UserPreferencesEntity();n.setUserKey(DEV_USER);return n;});e.setFavoriteWatchlists(mapper.writeValueAsString(r.favoriteWatchlists()));e.setFavoriteSymbols(mapper.writeValueAsString(r.favoriteSymbols()));e.setWatchlistColumns(mapper.writeValueAsString(r.watchlistColumns()));return preferenceDto(preferences.save(e));}catch(Exception ex){throw new IllegalArgumentException("Invalid preferences");}}
 private PreferencesResponse preferenceDto(UserPreferencesEntity e){try{return new PreferencesResponse(mapper.readValue(e.getFavoriteWatchlists(),new TypeReference<>(){}),mapper.readValue(e.getFavoriteSymbols(),new TypeReference<>(){}),mapper.readValue(e.getWatchlistColumns(),new TypeReference<>(){}));}catch(Exception ex){throw new IllegalStateException("Stored preferences are invalid");}}
}
